// Monta assunto + HTML do e-mail do lembrete com a identidade visual da BMS Consultoria Tributária.
// Usa o mesmo texto que já vai no WhatsApp (mensagem_visual), só formatado em parágrafos.
// Um parágrafo que é só um link vira botão. O logo vai DENTRO do e-mail (anexo "inline"): Gmail e
// Outlook não mostram imagem SVG e muitos e-mails bloqueiam imagens que vêm de um endereço externo.
var esc = function (s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};

var LOGO_BASE64 = '';
var AZUL_BMS = '#021D44';
var LARANJA_BMS = '#FF7F00';
var COR_TEXTO = '#14233D';

var motivo = $('Montar o body da requisição').first().json.motivo_disparo;
var corpo = $('Montar o body da requisição').first().json.mensagem_visual;
var horario = $('Preparar variáveis do lead').first().json.horario_reuniao;

var horarioFormatado = horario
  ? new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(horario))
  : '';

var assuntos = {
  reuniao_amanha: 'Confirmando nossa reunião de amanhã às ' + horarioFormatado,
  reuniao_hoje: 'Lembrete: nossa reunião é hoje às ' + horarioFormatado,
  reuniao_proximos_10min: 'Começamos em instantes — segue o link'
};
var subject = assuntos[motivo] || 'Lembrete da nossa reunião';

var paragrafos = String(corpo || '')
  .split(/\n\s*\n/)
  .map(function (p) { return p.trim(); })
  .filter(Boolean)
  .map(function (p) {
    if (/^https?:\/\/\S+$/.test(p)) {
      return '<div style="text-align:center;margin:8px 0 16px 0;"><a href="' + esc(p) + '" style="display:inline-block;background:' + AZUL_BMS + ';color:#ffffff;text-decoration:none;padding:14px 28px;border-radius:4px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:600;letter-spacing:0.04em;">Entrar na reunião</a></div>';
    }
    return '<p style="margin:0 0 16px 0;font-family:Georgia,serif;font-size:14px;line-height:1.7;color:' + COR_TEXTO + ';">' + esc(p).replace(/\n/g, '<br/>') + '</p>';
  })
  .join('');

var html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /><title>BMS Consultoria Tributária</title></head>'
  + '<body style="margin:0;padding:0;background:#F2F4F7;font-family:Georgia,serif;color:' + COR_TEXTO + ';">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#F2F4F7;padding:32px 12px;"><tr><td align="center">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #DDE3EC;border-radius:6px;overflow:hidden;">'
  + '<tr><td style="background:' + AZUL_BMS + ';padding:30px 32px;text-align:center;">'
  + '<img src="cid:bms-logo" alt="BMS Consultoria Tributária" width="200" height="49" style="display:block;margin:0 auto;border:0;width:200px;height:auto;max-width:100%;" />'
  + '</td></tr><tr><td style="height:3px;background:' + LARANJA_BMS + ';font-size:0;line-height:0;">&nbsp;</td></tr>'
  + '<tr><td style="padding:36px 32px 8px 32px;">' + paragrafos + '</td></tr>'
  + '<tr><td style="border-top:1px solid #DDE3EC;"></td></tr>'
  + '<tr><td style="padding:20px 32px;background:#F7F8FA;text-align:center;"><p style="margin:0;font-family:Georgia,serif;font-size:13px;color:' + AZUL_BMS + ';font-weight:600;">BMS Consultoria Tributária</p></td></tr>'
  + '</table></td></tr></table></body></html>';

var anexos = [{ filename: 'bms-logo.png', content: LOGO_BASE64, content_type: 'image/png', content_id: 'bms-logo' }];

return [{ json: Object.assign({}, $json, { subject: subject, html: html, anexos: anexos }) }];

